      "customWidth": "50",
      "name": "desc-tool"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "dependencies | where tostring(customDimensions['gen_ai.operation.name'])=='execute_tool' or isnotempty(tostring(customDimensions['gen_ai.tool.name'])) | extend tool=tostring(customDimensions['gen_ai.tool.name']) | summarize calls=count(), failures=countif(success==false), avg_ms=round(avg(duration),0) by tool | extend error_rate_pct=round(100.0*failures/calls,1) | project tool, calls, failures, error_rate_pct, avg_ms | order by error_rate_pct desc, calls desc",
